-- IPA source-reviewed 2021 project and service management questions.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q51','exam-fe','WBS','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問51・改編】ソフトウェア開発プロジェクトでWBSを使用する目的はどれか。','[{"id":"a","text":"開発期間と費用のトレードオフから総費用を最適化する"},{"id":"b","text":"作業順序を明確にしクリティカルパスを把握する"},{"id":"c","text":"作業日程を横棒で表し開始・終了と進捗を示す"},{"id":"d","text":"作業を階層的に詳細化し管理可能な大きさに細分化する"}]','"d"','WBSは作業を階層的に分解し管理しやすくする。日程の横棒表示はガントチャート。 中文：WBS将工作分层细化为可管理的部分；横条日程图是甘特图。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q52','exam-fe','アローダイアグラム','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問52・改編】次の作業ネットワークでDのみ10日から6日に短縮できる。全体の所要日数は何日短縮されるか。開始→分岐:A5日、分岐→上:B3日、分岐→下:C5日、下→上:D10日、上→右上:E5日、下→右下:F12日、右上→右下:ダミー0日、右上→終了:G3日、右下→終了:H6日。','[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"3"},{"id":"d","text":"4"}]','"c"','短縮前の最長経路はA+C+D+E+ダミー+H=31日。短縮後はA+C+F+H=28日が最長で、3日短縮。 中文：关键路径从31天降到28天，因此缩短3天。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q53','exam-fe','プロジェクト進捗','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問53・改編】工程別の工数比率は基本設計0.08、詳細設計0.16、プログラム設計0.20、プログラミング0.25、テスト0.31。プログラム設計までは完了し、全3,000本中1,200本をプログラミング済み。各プログラムの開発工数は同じとすると、全体の進捗は何％か。','[{"id":"a","text":"40"},{"id":"b","text":"44"},{"id":"c","text":"54"},{"id":"d","text":"59"}]','"c"','完了工程は0.08+0.16+0.20=0.44。プログラミングは0.25×1200/3000=0.10で、合計54%。 中文：已完成阶段44%，编程阶段完成0.25×40%=10%，合计54%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q54','exam-fe','工数と期間','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問54・改編】期間（月）=2.5×工数（人月）の3乗根という近似式で、工数4,096人月の期間は何か月か。','[{"id":"a","text":"16"},{"id":"b","text":"40"},{"id":"c","text":"64"},{"id":"d","text":"160"}]','"b"','4,096の3乗根は16。2.5×16=40か月。 中文：4096的立方根为16，乘2.5得到40个月。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q55','exam-fe','エスカレーション','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問55・改編】サービスマネジメントで、一次サポートが専門技能を持つ二次サポートにインシデントの解決を依頼することを何というか。','[{"id":"a","text":"回避策"},{"id":"b","text":"継続的改善"},{"id":"c","text":"エスカレーション"},{"id":"d","text":"予防処置"}]','"c"','専門的な上位または別の担当へ対応を移すことをエスカレーションという。 中文：将事件转交给更专业的支持层处理称为升级。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q56','exam-fe','容量・能力管理','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問56・改編】サービスの容量・能力や性能を予測する活動のうち、傾向分析はどれか。','[{"id":"a","text":"資源の利用状況を時系列で把握し将来の変化を予測する"},{"id":"b","text":"待ち行列理論などの数学的技法で応答時間やスループットを予測する"},{"id":"c","text":"模擬トランザクションを発生させ応答時間やスループットを予測する"},{"id":"d","text":"現在の性能を正確に反映するモデルを作成する"}]','"a"','傾向分析は過去の時系列データから将来の変化を推定する。 中文：趋势分析利用历史时间序列预测未来变化。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q58','exam-fe','アクセス権監査','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問58・改編】利用者アクセス権の管理状況の監査で、指摘すべき事項はどれか。','[{"id":"a","text":"IDとパスワードの遵守事項を規程に定め利用者に周知していた"},{"id":"b","text":"業務部門長が所属者のアクセス権を定期的にレビューしていた"},{"id":"c","text":"アクセス権の付与・変更・削除の手続を規程に定めていた"},{"id":"d","text":"退職・異動者のアクセス権の削除・変更を年度初めにまとめて実施していた"}]','"d"','退職・異動時の権限変更を長期間遅らせると不要なアクセス権が残る。 中文：离职或调岗权限若等到年度开始才处理，会留下不必要的访问权限。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q59','exam-fe','システム監査技法','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問59・改編】システム監査手続で利用する技法について適切なものはどれか。','[{"id":"a","text":"インタビュー法は監査人が関係者に口頭で問い合わせ回答を得る技法"},{"id":"b","text":"現地調査は監査対象部門の業務時間外に実施しなければならない"},{"id":"c","text":"コンピュータ支援監査は必ず簡単な専用ソフトウェアだけを使わなければならない"},{"id":"d","text":"チェックリスト法は対象部門がまとめた見解のみを監査人が点検する技法"}]','"a"','インタビューは監査人が関係者へ質問し証拠を得る方法。ほかの選択肢は不必要な限定や誤った定義を含む。 中文：访谈法由审计人员向相关人员口头提问并取得回答。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q60','exam-fe','バックアップ媒体の監査','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問60・改編】機密情報を含むバックアップ媒体を外部保管業者へ引き渡す際、監査報告書に指摘すべき状況はどれか。','[{"id":"a","text":"定期的に保管状況を確認する契約を結んで引き渡す"},{"id":"b","text":"機密保持条項を含む委託契約を結んで引き渡す"},{"id":"c","text":"専用記録簿に日付と内容を記録し受領印を得る"},{"id":"d","text":"媒体を段ボール箱に入れて業者に引き渡す"}]','"d"','機密媒体は輸送時の盗難・漏えい対策が必要。単に段ボール箱へ入れるだけでは十分な保護を確認できない。 中文：机密介质交接需要运输与保密措施，仅装入纸箱不足以保证安全。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
